def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], coords: np.ndarray, demand: np.ndarray, distance_matrix: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.
    Args:
        archive: A list of tuples, where each tuple contains:
            - solution: A list of numpy arrays, each representing a vehicle route. 
                        Each route starts and ends at the depot (node index 0), e.g., [0, 3, 5, 0].
            - objective: A tuple of two float values (total_distance, makespan), 
                        representing the two objective values of the solution.

        coords: A numpy array of shape (n_nodes, 2), representing (x, y) coordinates of each node (depot + customers).
        demand: A numpy array of shape (n_nodes,), where demand[i] is the demand of node i. The depot has demand 0.
        distance_matrix: A numpy array of shape (n_nodes, n_nodes), where [i][j] is the Euclidean distance between node i and j.
        capacity: A float representing the maximum capacity of each vehicle.

    Returns:
        A new neighbor solution.
    """
    def pareto_dominance(obj1, obj2):
        return (obj1[0] <= obj2[0] and obj1[1] <= obj2[1] and (obj1[0] < obj2[0] or obj1[1] < obj2[1]))

    def crowding_distance(solutions, objectives):
        distances = np.zeros(len(solutions))
        for m in range(2):
            sorted_idx = np.argsort([obj[m] for _, obj in solutions])
            distances[sorted_idx[0]] = distances[sorted_idx[-1]] = float('inf')
            for i in range(1, len(solutions)-1):
                distances[sorted_idx[i]] += (solutions[sorted_idx[i+1]][1][m] - solutions[sorted_idx[i-1]][1][m])
        return distances

    # Select solution using Pareto frontier guidance
    non_dominated = []
    for sol, obj in archive:
        is_dominated = False
        for _, comp_obj in archive:
            if pareto_dominance(comp_obj, obj):
                is_dominated = True
                break
        if not is_dominated:
            non_dominated.append((sol, obj))

    if len(non_dominated) > 1:
        distances = crowding_distance(non_dominated, [obj for _, obj in non_dominated])
        selected_idx = np.argmax(distances)
        selected_solution = non_dominated[selected_idx][0]
    else:
        selected_solution = random.choice([sol for sol, _ in archive])

    new_solution = [route.copy() for route in selected_solution]

    # Dynamic route segmentation based on spatial-demand balance
    for route_idx in range(len(new_solution)):
        route = new_solution[route_idx]
        if len(route) > 4:
            spatial_center = np.mean(coords[route[1:-1]], axis=0)
            demand_balance = np.sum(demand[route[1:-1]]) / capacity

            if random.random() < 0.7 * (1 - demand_balance):
                split_pos = len(route) // 2
                route1 = np.concatenate([route[:split_pos], [0]])
                route2 = np.concatenate([[0], route[split_pos:]])
                new_solution[route_idx] = route1
                new_solution.insert(route_idx+1, route2)

    # Spatial-demand aware route fusion
    if len(new_solution) > 1 and random.random() < 0.6:
        route_centers = []
        for route in new_solution:
            if len(route) > 2:
                route_coords = coords[route[1:-1]]
                spatial_var = np.max(np.linalg.norm(route_coords - np.mean(route_coords, axis=0), axis=1))
                route_centers.append((np.mean(route_coords, axis=0), spatial_var, np.sum(demand[route[1:-1]])))

        if len(route_centers) > 1:
            fusion_candidates = []
            for i in range(len(route_centers)):
                for j in range(i+1, len(route_centers)):
                    spatial_dist = np.linalg.norm(route_centers[i][0] - route_centers[j][0])
                    spatial_similarity = 1 / (1 + spatial_dist)
                    demand_similarity = 1 - abs(route_centers[i][2] - route_centers[j][2]) / capacity
                    fusion_score = 0.6 * spatial_similarity + 0.4 * demand_similarity
                    fusion_candidates.append((fusion_score, i, j))

            fusion_candidates.sort(reverse=True, key=lambda x: x[0])
            for _, i, j in fusion_candidates[:min(2, len(fusion_candidates))]:
                route_i = new_solution[i]
                route_j = new_solution[j]

                if np.sum(demand[route_i[1:-1]]) + np.sum(demand[route_j[1:-1]]) <= capacity:
                    new_route = np.concatenate([route_i[:-1], route_j[1:]])
                    new_solution[i] = new_route
                    new_solution.pop(j)
                    break

    # Capacity-constrained probabilistic route splitting
    for route_idx in range(len(new_solution)):
        route = new_solution[route_idx]
        if len(route) > 5 and random.random() < 0.5:
            total_demand = np.sum(demand[route[1:-1]])
            if total_demand > 0.8 * capacity:
                split_pos = np.argmax(np.cumsum(demand[route[1:-1]]) > 0.9 * capacity) + 1
                route1 = np.concatenate([route[:split_pos+1], [0]])
                route2 = np.concatenate([[0], route[split_pos+1:]])
                new_solution[route_idx] = route1
                new_solution.insert(route_idx+1, route2)

    # Spatial proximity-based route inversion
    for route_idx in range(len(new_solution)):
        route = new_solution[route_idx]
        if len(route) > 6:
            for _ in range(2):
                start = random.randint(1, len(route)-4)
                end = random.randint(start+2, len(route)-2)
                segment = route[start:end]

                if len(segment) > 2:
                    inverted_segment = segment[::-1]
                    new_route = np.concatenate([route[:start], inverted_segment, route[end:]])

                    if np.sum(demand[new_route[1:-1]]) <= capacity:
                        new_solution[route_idx] = new_route
                        break

    # Final capacity validation and repair
    for route_idx in range(len(new_solution)):
        route = new_solution[route_idx]
        if np.sum(demand[route[1:-1]]) > capacity:
            cumulative_demand = 0
            split_pos = -1
            for i in range(1, len(route)-1):
                cumulative_demand += demand[route[i]]
                if cumulative_demand > capacity:
                    split_pos = i
                    break

            if split_pos > 1:
                route1 = np.concatenate([route[:split_pos], [0]])
                route2 = np.concatenate([[0], route[split_pos:]])
                new_solution[route_idx] = route1
                new_solution.insert(route_idx+1, route2)

    return new_solution
